	addForward[wire.CreateWorkPointArgs](s, "create_work_point", "Create a datum work point fixed at a position (at:[x,y,z], model units). Returns its ref (e.g. \"point/1\") to use as a point input — three points make a three-points work plane, or re-point such a plane's slot via redefine_work_plane.", wire.MethodWorkPointsCreate)
