	addForward[wire.AddAngularDimensionArgs](s, "drawing_add_angular_dimension", "Add an angular dimension on a drawing view between the two straight model edges nearest the pick points (x1,y1,x2,y2 sheet mm). The measured angle (degrees) is reported in valueDeg and updates with the model.", wire.MethodDrawingDimensionsAddAngular)
	addForward[wire.AddArcLengthDimensionArgs](s, "drawing_add_arc_length_dimension", "Add an arc-length dimension on a drawing view, attached to the circular/arc model edge nearest the pick point (pickXmm/pickYmm sheet mm). It measures the edge's swept length (a full circle's circumference) with the dimension line following the arc. The value is the true model size and updates with the model.", wire.MethodDrawingDimensionsAddArcLength)
	addForward[wire.AddAuxiliaryViewArgs](s, "drawing_add_auxiliary_view", "Add an auxiliary view off a parent view: projected perpendicular to a fold line at foldAngleDeg (0 folds down like a top view, 90 folds to the side), inheriting the parent's scale/style; placed at centerXmm/centerYmm. Shows an inclined face true-size.", wire.MethodDrawingViewsAddAuxiliary)
	addForward[wire.AddBalloonArgs](s, "drawing_add_balloon", "Add a balloon at a sheet point (xmm/ymm = circle centre): a circle holding the parts-list item number, with an optional leader to the component it tags (leaderXmm/leaderYmm). Balloons reference parts-list items.", wire.MethodDrawingAnnotationsAddBalloon)
	addForward[wire.AddBaseViewArgs](s, "drawing_add_base_view", "Add a base view of the drawing's referenced model (orientation = front|top|right|back|left|bottom|iso, style = hiddenLine|wireframe|shaded, scale e.g. 0.5 for 1:2) centred at centerXmm/centerYmm; computes visible/hidden edges.", wire.MethodDrawingViewsAddBase)
	addForward[wire.AddDimensionSetArgs](s, "drawing_add_baseline_dimensions", "Add a baseline dimension set on a drawing view: linear dimensions from the first pick point to each of the other points (each [x,y] sheet mm, snapped to model vertices), stacked. type = aligned|horizontal|vertical. The values update with the model.", wire.MethodDrawingDimensionsAddBaseline)
	addForward[wire.AddBreakViewArgs](s, "drawing_add_break_view", "Add a break view: the parent view compressed by removing a band (orientation = horizontal removes a vertical band, vertical removes a horizontal one) between gapStartMm and gapEndMm on the parent (sheet mm), with break lines at the cut; placed at centerXmm/centerYmm.", wire.MethodDrawingViewsAddBreak)
	addForward[wire.AddBreakoutViewArgs](s, "drawing_add_breakout_view", "Add a breakout view off a parent: a local cut-away revealing the interior inside the circular region (boundaryXmm/boundaryYmm/radiusMm on the parent, sheet mm); placed at centerXmm/centerYmm.", wire.MethodDrawingViewsAddBreakout)
	addForward[wire.AddCenterMarksArgs](s, "drawing_add_center_marks", "Add a centre mark (crosshair) at the centre of every circular model edge in a drawing view (the auto centre-mark-all-holes action). Each mark attaches to its edge and re-projects when the model changes.", wire.MethodDrawingAnnotationsAddCenterMarks)
	addForward[wire.AddCenterlinesArgs](s, "drawing_add_centerlines", "Add the horizontal and vertical dash-dot symmetry centerlines through a drawing view's centre, spanning its extent. The lines re-derive from the view's bounds, so they track the model.", wire.MethodDrawingAnnotationsAddCenterlines)
	addForward[wire.AddDimensionSetArgs](s, "drawing_add_chain_dimensions", "Add a chain dimension set on a drawing view: linear dimensions between consecutive pick points (each [x,y] sheet mm, snapped to model vertices), running in a line. type = aligned|horizontal|vertical. The values update with the model.", wire.MethodDrawingDimensionsAddChain)
	addForward[wire.AddCoGMarkerArgs](s, "drawing_add_cog_marker", "Add a centre-of-gravity marker on a drawing view (viewName); it is placed at the referenced model's centre of mass projected into that view and updates with the model.", wire.MethodDrawingAnnotationsAddCoG)
	addForward[wire.AddCustomTableArgs](s, "drawing_add_custom_table", "Add a general-purpose table at a sheet point (xmm/ymm = top-left) with the given column headers and rows (each row's cells align to the headers). The rowCount in the result is the data-row count.", wire.MethodDrawingAnnotationsAddCustomTable)
	addForward[wire.AddDatumFeatureArgs](s, "drawing_add_datum_feature", "Add a GD&T datum feature symbol at a sheet point (xmm/ymm): the datum letter (e.g. \"A\") in a box with a filled datum triangle, marking a datum that feature control frames reference.", wire.MethodDrawingAnnotationsAddDatum)
	addForward[wire.AddDetailViewArgs](s, "drawing_add_detail_view", "Add a detail view: a magnified circular region (boundaryXmm/boundaryYmm/radiusMm on the parent, sheet mm) of a parent view, at the larger scale, placed at centerXmm/centerYmm.", wire.MethodDrawingViewsAddDetail)
	addForward[wire.AddDraftViewArgs](s, "drawing_add_draft_view", "Add a draft view: a model-less framed container (widthMm × heightMm, sheet mm) at centerXmm/centerYmm for manually-drawn 2D geometry.", wire.MethodDrawingViewsAddDraft)
	addForward[wire.AddFeatureControlFrameArgs](s, "drawing_add_feature_control_frame", "Add a GD&T feature control frame at a sheet point (xmm/ymm): a boxed geometric-tolerance callout with a characteristic (types.GeometricCharacteristic wire spelling, e.g. position|flatness|perpendicularity|parallelism|straightness|circularity), a tolerance value, and ordered datum reference letters.", wire.MethodDrawingAnnotationsAddFCF)
	addForward[wire.AddHatchRegionArgs](s, "drawing_add_hatch_region", "Fill a rectangle (xmm/ymm/widthMm/heightMm, sheet mm) with a hatch pattern (general|cross|ansi31) on a drawing sketch; scaleMm overrides the line spacing. The region's fill lines render as sketch curves.", wire.MethodDrawingSketchesAddHatch)
	addForward[wire.AddHoleNotesArgs](s, "drawing_add_hole_notes", "Add hole notes to a base view (viewName): a leadered Ø-diameter callout computed from each hole's circular edge and re-resolved when the model changes. quantity \"combined\" groups holes by diameter into one \"<n>x Ø<d>\" callout per size (default \"perHole\" = one per hole). Optional format template with {d} (diameter) and {n} (count) placeholders, e.g. \"Ø{d} THRU\". The rowCount in the result is the callout count.", wire.MethodDrawingAnnotationsAddHoleNotes)
	addForward[wire.AddHoleTableArgs](s, "drawing_add_hole_table", "Add a hole table at a sheet point (xmm/ymm = top-left) listing every circular edge in a base view: HOLE / X / Y (from the view's datum origin) / ⌀ (diameter). The rowCount in the result is the hole count; the table updates with the model.", wire.MethodDrawingAnnotationsAddHoleTable)
	addForward[wire.AddLinearDimensionArgs](s, "drawing_add_linear_dimension", "Add a linear dimension on a drawing view between two pick points (x1,y1,x2,y2 in sheet mm, each snapped to the nearest projected model vertex). type = aligned (true distance, default) | horizontal | vertical; offsetMm stands the dimension line off the points. The measured value is the true model size and updates with the model.", wire.MethodDrawingDimensionsAddLinear)
	addForward[wire.AddDrawingNoteArgs](s, "drawing_add_note", "Add a free text note anchored at a sheet point (xmm/ymm); if leaderXmm/leaderYmm are given, a leader is drawn from the note to that point.", wire.MethodDrawingAnnotationsAddNote)
	addForward[wire.AddOrdinateDimensionsArgs](s, "drawing_add_ordinate_dimensions", "Add an ordinate dimension set on a drawing view: one dimension per point measuring its offset from a common datum ([x,y] sheet mm, snapped to model vertices) along axis = horizontal (view-X, default) | vertical (view-Y). Each is drawn as a leader to its value with no dimension line; the values update with the model.", wire.MethodDrawingDimensionsAddOrdinate)
	addForward[wire.AddPartsListArgs](s, "drawing_add_parts_list", "Add a parts list table at a sheet point (xmm/ymm = top-left): a grid sourced from the referenced assembly's parts-only BOM (item number, part number, description, quantity). The rowCount in the result is the number of BOM items; the table updates with the assembly.", wire.MethodDrawingAnnotationsAddPartsList)
	addForward[wire.AddProjectedViewArgs](s, "drawing_add_projected_view", "Add a projected view off a base view (direction = right|left|up|down), inheriting the base's scale/style; placed at centerXmm/centerYmm.", wire.MethodDrawingViewsAddProjected)
	addForward[wire.AddRadialDimensionArgs](s, "drawing_add_radial_dimension", "Add a radius or diameter dimension on a drawing view, attached to the circular model edge nearest the pick point (pickXmm/pickYmm sheet mm). type = radius (default) | diameter. The value is the true model size and updates with the model.", wire.MethodDrawingDimensionsAddRadial)
	addForward[wire.AddRevisionCloudArgs](s, "drawing_add_revision_cloud", "Add a revision cloud (scalloped markup) over the sheet rectangle xmm/ymm/widthMm/heightMm, with an optional revision tag.", wire.MethodDrawingAnnotationsAddRevisionCloud)
	addForward[wire.AddRevisionTableArgs](s, "drawing_add_revision_table", "Add a revision table at a sheet point (xmm/ymm = top-left) with rows of {revision, date, description}, recording the drawing's change history. The rowCount in the result is the revision count.", wire.MethodDrawingAnnotationsAddRevTable)
	addForward[wire.AddRevisionTagArgs](s, "drawing_add_revision_tag", "Add a revision tag (a triangle holding the revision letter) centred at a sheet point (xmm/ymm), flagging where that revision changed the drawing.", wire.MethodDrawingAnnotationsAddRevTag)
	addForward[wire.AddSectionViewArgs](s, "drawing_add_section_view", "Add a section view off a parent view: the model is cut by the plane through the section line (x1,y1)-(x2,y2) drawn on the parent (sheet mm), the near half removed, the cut outline drawn bold and the exposed faces hatched; placed at centerXmm/centerYmm.", wire.MethodDrawingViewsAddSection)
	addForward[wire.AddSheetArgs](s, "drawing_add_sheet", "Add a sheet to the active drawing (size = a0..a4|ansiA..ansiE|custom, orientation = portrait|landscape; for custom give widthMm/heightMm); an empty name auto-assigns. Becomes the active sheet.", wire.MethodDrawingAddSheet)
	addForward[wire.AddDrawingSketchArgs](s, "drawing_add_sketch", "Add a new empty 2D sketch to the active sheet (sheet-millimetre space); add geometry to it with drawing_add_sketch_entity.", wire.MethodDrawingSketchesAdd)
	addForward[wire.AddDrawingSketchEntityArgs](s, "drawing_add_sketch_entity", "Add an entity to a drawing sketch (sketchName): kind line|circle|rectangle, points = sheet-mm [x,y] pairs (2 for line endpoints / rectangle corners, 1 for a circle centre with radiusMm).", wire.MethodDrawingSketchesAddEntity)
	addForward[wire.AddSliceViewArgs](s, "drawing_add_slice_view", "Add a slice view off a parent: only the zero-thickness slice outline at the section line (x1,y1)-(x2,y2) on the parent (sheet mm), with nothing projected behind it; placed at centerXmm/centerYmm.", wire.MethodDrawingViewsAddSlice)
	addForward[wire.AddSurfaceTextureArgs](s, "drawing_add_surface_texture", "Add an ISO 1302 surface texture symbol at a sheet point (xmm/ymm): the roughness checkmark glyph with a finish value (roughness, e.g. \"1.6\"). materialRemoval = any (basic, default) | required (machined, with bar) | prohibited (as-cast, with vertex circle).", wire.MethodDrawingAnnotationsAddSurfaceText)
	addForward[wire.DeleteAnnotationArgs](s, "drawing_delete_annotation", "Delete a drawing annotation by name.", wire.MethodDrawingAnnotationsDelete)
	addForward[wire.DeleteDimensionArgs](s, "drawing_delete_dimension", "Delete a drawing dimension by name.", wire.MethodDrawingDimensionsDelete)
	addForward[wire.DeleteViewArgs](s, "drawing_delete_view", "Delete a drawing view by name (deleting a base view also removes views projected from it).", wire.MethodDrawingViewsDelete)
	addForward[wire.ExportDrawingDXFArgs](s, "drawing_export_dxf", "Export the active drawing sheet to a DXF file (path, version r2000|r2018): view edges on Visible/Hidden layers, the border, and the title-block grid + field text.", wire.MethodDrawingExportDXF)
	addForward[struct{}](s, "drawing_get_active_style", "Read the active drawing standard's style preset — dimension (text/arrow size, decimals, unit, line weight), text (font, height) and line (weight) styles.", wire.MethodDrawingStylesGetActiveStyle)
	addForward[struct{}](s, "drawing_list_annotations", "List the active sheet's drawing annotations (name, kind = cog|revisionCloud, the view a CoG marker is on, a revision cloud's tag, and curve count).", wire.MethodDrawingAnnotationsList)
	addForward[struct{}](s, "drawing_list_dimensions", "List the active sheet's drawing dimensions (name, type = aligned|horizontal|vertical, the view, measured value in mm, displayed text, curve count).", wire.MethodDrawingDimensionsList)
	addForward[struct{}](s, "drawing_list_sheets", "List the active drawing document's sheets (name, size, orientation, width/height in mm, border/title-block presence; the active sheet is flagged) and the primary referenced model.", wire.MethodDrawingListSheets)
	addForward[struct{}](s, "drawing_list_sketches", "List the active sheet's drawing sketches (name, entity count, curve count).", wire.MethodDrawingSketchesList)
	addForward[struct{}](s, "drawing_list_standards", "List the active drawing's available drafting standards (iso, ansi) and which is active.", wire.MethodDrawingStylesListStandards)
	addForward[struct{}](s, "drawing_list_views", "List the active sheet's drawing views (name, base/projected, orientation, scale, style, sheet centre, and visible/hidden curve counts).", wire.MethodDrawingViewsList)
	addForward[wire.RemoveSheetArgs](s, "drawing_remove_sheet", "Remove the named sheet from the active drawing (a drawing must keep at least one sheet).", wire.MethodDrawingRemoveSheet)
	addForward[wire.SetActiveSheetArgs](s, "drawing_set_active_sheet", "Make the named sheet the active sheet of the active drawing.", wire.MethodDrawingSetActiveSheet)
	addForward[wire.SetModelReferenceArgs](s, "drawing_set_model_reference", "Set the drawing's primary referenced model by full document name (its iProperties feed the title block); an empty name clears the reference.", wire.MethodDrawingSetModelReference)
	addForward[wire.SetStandardArgs](s, "drawing_set_standard", "Switch the active drawing's drafting standard (iso|ansi); returns the new active style preset (dimension/text/line), so the appearance change is visible in one call.", wire.MethodDrawingStylesSetStandard)
	addForward[wire.TitleBlockFieldsArgs](s, "drawing_title_block_fields", "Read a sheet's title-block resolved fields (name, value, and source iProperty token); an empty sheet uses the active sheet. Fields are empty when the sheet has no title block.", wire.MethodDrawingTitleBlockFields)
	addForward[wire.ViewCurvesArgs](s, "drawing_view_curves", "Read a view's hidden-line drawing curves: 2D segments (sheet mm) flagged visible (solid) or hidden (dashed), each carrying the source model edge's reference key.", wire.MethodDrawingViewsCurves)
	addForward[wire.DriveJointArgs](s, "drive_joint", "Drive a joint's variable through a range (settings: start, end, step in radians for angular / cm for linear; optional variable angular|linear, repetitionCount, repetitionStartEndStart ping-pong, collisionDetection). Re-solves each step; returns the frames (driven value + occurrence transforms), halting at the first interfering frame when collision detection is on.", wire.MethodAssemblyDrivePreview)
	addForward[wire.DriveSketch3DDimensionArgs](s, "drive_sketch3d_dimension", "Change a 3D-sketch dimension's expression and recompute.", wire.MethodSketch3DDriveDimension)
	addForward[wire.DriveDimensionArgs](s, "drive_sketch_dimension", "Change a dimension's expression (and optionally its driven flag / animation limits) and recompute.", wire.MethodSketchDriveDimension)
